/**
 * The transport admission projection — `{NORA_BRIDGE_PROJECTION_DIR}/whatsapp.json`,
 * generated by the app's own policy/identity code and mounted read-only on a
 * shared volume. The bridge polls mtime and applies the LAST GOOD file: a file
 * that disappears or fails to parse degrades health, never silently widens or
 * narrows admission.
 *
 * Shape (frozen wire §projection):
 *   { revision:int in [0,2^53-1], generated_ms:int, enabled:bool,
 *     account_key:str, rooms:[conversation_id...],
 *     dm_allowed_senders:[sender_id...], self_aliases:[id...],
 *     deterministic_triggers:[str|{pattern}...], receipt_emoji:str|null,
 *     room_receipt_senders:{conversation_id:[sender_id...|'*']} }
 *
 * Rules (design 02 §admission + the private-projection amendment):
 *   - no valid projection at startup → refuse content capture/receipts
 *     (everything is denied)
 *   - denied/unconfigured room → no body/attachment capture, no journal row
 *   - allowed-room capture does NOT grant receipts. A group receipt
 *     additionally requires the sender in room_receipt_senders[room] (or the
 *     literal '*' policy wildcard) AND deterministic addressed-ness
 *     (mention / self-reply / trigger) under the current enabled policy; a
 *     missing map or room entry is a deny. DM receipts are person-scoped by
 *     dm_allowed_senders — the group grant never substitutes and the DM list
 *     never authorizes group receipts.
 */
import { readFileSync, statSync } from 'node:fs';
import path from 'node:path';

export class Projection {
  constructor(dir, platform, { log = () => {}, pollMs = 2000 } = {}) {
    this.file = path.join(dir || '/bridge-projection', `${platform}.json`);
    this.log = log;
    this.pollMs = pollMs;
    this.current = null;         // last-good parsed projection
    this.stale = false;          // a reload failed since last good
    this.mtimeMs = null;
    this._timer = null;
  }

  /** Read + validate once. Returns the projection or null (invalid/absent). */
  load() {
    let data;
    try {
      data = JSON.parse(readFileSync(this.file, 'utf8'));
    } catch {
      return null;
    }
    if (!data || typeof data !== 'object' || Array.isArray(data)) return null;
    if (typeof data.enabled !== 'boolean') return null;
    // revision must be exact across JSON/JS/Go/Python — bounded to 2^53-1.
    if (!Number.isInteger(data.revision) || data.revision < 0
        || data.revision > 9007199254740991) return null;
    return data;
  }

  /** Startup load + the mtime poll loop. `this.stale` marks last-good mode. */
  start() {
    this._tick(true);
    this._timer = setInterval(() => this._tick(false), this.pollMs);
    this._timer.unref();
  }

  stop() {
    if (this._timer) clearInterval(this._timer);
    this._timer = null;
  }

  _tick(first) {
    let mtime = null;
    try {
      mtime = statSync(this.file).mtimeMs;
    } catch { /* absent file */ }
    if (!first && mtime !== null && mtime === this.mtimeMs) return;
    const next = this.load();
    if (next) {
      this.mtimeMs = mtime;
      const changed = !this.current || this.current.revision !== next.revision;
      this.current = next;
      this.stale = false;
      if (changed) this.log(`admission projection rev ${next.revision} loaded (enabled=${next.enabled})`);
    } else {
      this.stale = this.current !== null || !first;
      if (first || this.current) {
        this.log('admission projection unavailable — keeping last-good; capture stays restricted to it');
      }
    }
  }

  /** The revision stamped on envelopes; null before any valid projection. */
  get revision() {
    return this.current ? (Number.isInteger(this.current.revision) ? this.current.revision : 0) : null;
  }

  get valid() { return this.current !== null; }

  /**
   * Whether this event may be captured at all (journal, attachments, bodies).
   * `enabled` is the whole-account kill switch; otherwise the room list admits
   * groups and listed DM senders admit 1:1s.
   */
  admitted(conversationId, senderId, conversationType) {
    const p = this.current;
    if (!p || !p.enabled) return false;
    if (Array.isArray(p.rooms) && p.rooms.includes(conversationId)) return true;
    return conversationType === 'dm'
      && Array.isArray(p.dm_allowed_senders)
      && p.dm_allowed_senders.includes(senderId);
  }

  /**
   * Queued-receipt eligibility: sender authorization AND deterministic
   * addressed-ness under the current enabled policy. `msg` is the
   * normalized message dict (its `mentions`/`quote.author_id`/`body` are the
   * only inputs — no model, no policy re-evaluation).
   */
  addressed(msg) {
    const p = this.current;
    if (!p || !p.enabled) return false;
    if (msg.conversation_type === 'dm') {
      // Person-scoped: the DM list itself, never a group grant.
      return Array.isArray(p.dm_allowed_senders)
        && p.dm_allowed_senders.includes(msg.sender_id);
    }
    // Group receipts need a per-room SENDER grant — membership or the
    // literal '*' policy wildcard. A missing map or room entry is a deny:
    // rooms authorize capture, not receipts. The DM list never substitutes.
    const grants = (p.room_receipt_senders && typeof p.room_receipt_senders === 'object')
      ? p.room_receipt_senders[msg.conversation_id] : null;
    if (!Array.isArray(grants)) return false;
    if (!(grants.includes('*') || grants.includes(msg.sender_id))) return false;
    // Then deterministic addressed-ness: mention, self-reply, or trigger.
    const aliases = new Set(Array.isArray(p.self_aliases) ? p.self_aliases : []);
    if (aliases.size) {
      if (Array.isArray(msg.mentions) && msg.mentions.some((m) => aliases.has(m))) return true;
      if (msg.quote && aliases.has(msg.quote.author_id)) return true;
    }
    const body = typeof msg.body === 'string' ? msg.body : '';
    if (body && Array.isArray(p.deterministic_triggers)) {
      for (const t of p.deterministic_triggers) {
        const needle = typeof t === 'string' ? t : (t && typeof t.pattern === 'string' ? t.pattern : '');
        if (needle && body.includes(needle)) return true;
      }
    }
    return false;
  }

  /** The queued-receipt emoji, or null when receipts are disabled. */
  get receiptEmoji() {
    const p = this.current;
    return p && typeof p.receipt_emoji === 'string' && p.receipt_emoji ? p.receipt_emoji : null;
  }
}
